import{_ as t,o as a,c as r,ae as n}from"./chunks/framework.EHGTsUvI.js";const p=JSON.parse('{"title":"Key Management","description":"","frontmatter":{},"headers":[],"relativePath":"security/keys.md","filePath":"security/keys.md"}'),i={name:"security/keys.md"};function o(d,e,s,h,c,y){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="key-management" tabindex="-1">Key Management <a class="header-anchor" href="#key-management" aria-label="Permalink to &quot;Key Management&quot;">​</a></h1><h2 id="key-generation" tabindex="-1">Key Generation <a class="header-anchor" href="#key-generation" aria-label="Permalink to &quot;Key Generation&quot;">​</a></h2><p>Identity keys are generated deterministically from a BIP-39 mnemonic:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>24-word mnemonic → SHA-512 → Ed25519 seed (32 bytes) → Ed25519 keypair</span></span></code></pre></div><p>The mnemonic provides 256 bits of entropy and serves as the recovery mechanism.</p><h2 id="key-storage" tabindex="-1">Key Storage <a class="header-anchor" href="#key-storage" aria-label="Permalink to &quot;Key Storage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key Type</th><th>Storage</th></tr></thead><tbody><tr><td>Ed25519 private key</td><td>OS keystore (Keytar on Windows/macOS)</td></tr><tr><td>Share encryption keys</td><td>OS keystore (<code>pal-share-keys</code> service)</td></tr><tr><td>PIN hash</td><td>OS keystore (<code>pal-explorer</code> service)</td></tr><tr><td>Public key</td><td>Config file (plaintext)</td></tr><tr><td>Mnemonic</td><td>Shown once at creation, never stored</td></tr></tbody></table><p><strong>Linux fallback</strong>: When Keytar is unavailable, keys are stored in an encrypted file using AES-256-GCM with a machine-derived key.</p><h2 id="key-derivation" tabindex="-1">Key Derivation <a class="header-anchor" href="#key-derivation" aria-label="Permalink to &quot;Key Derivation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Purpose</th><th>Method</th></tr></thead><tbody><tr><td>Identity → Key exchange</td><td>Ed25519 → Curve25519 (<code>crypto_sign_ed25519_sk_to_curve25519</code>)</td></tr><tr><td>Share key → Manifest key</td><td><code>crypto_kdf_derive_from_key(shareKey, subkey_id=1)</code></td></tr><tr><td>Password → Encryption key</td><td>Argon2id (3 iterations, 64 MB)</td></tr><tr><td>Mnemonic → Seed</td><td>BIP-39 standard</td></tr></tbody></table><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery&quot;">​</a></h2><p>To recover your identity on a new device:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recover</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;word1 word2 word3 ... word24&quot;</span></span></code></pre></div><p>This deterministically regenerates the same Ed25519 keypair from the mnemonic.</p><h2 id="key-rotation" tabindex="-1">Key Rotation <a class="header-anchor" href="#key-rotation" aria-label="Permalink to &quot;Key Rotation&quot;">​</a></h2><p>Share keys are per-share and random. If a share is compromised, only that share&#39;s content is affected. Revoke the share and create a new one with a fresh key.</p><p>Identity keys are tied to the mnemonic and cannot be rotated without creating a new identity.</p>',17)])])}const k=t(i,[["render",o]]);export{p as __pageData,k as default};
